# Mutants of the level manifest: the .MNG parser, its arrays and queue, and its twelve kinds of item. Each text occurs exactly once in its file.
L = "GmLevelManifest.cpp"
I = "GmLevelManifestItems.cpp"

# Dropped as equivalent, with the reason:
# * request.m_unused[0] = 0 and request.m_path[0] = 0 at each word: nothing reads the first, and the second is overwritten before any item sees it.
# * request.m_context = 0 before a word sets it from a global: overwritten before any read.
# * The second test of an array pointer before each delete in both Free functions: the first test already answered it.
# * ClearLevelArrays in GmLevelManifest::Clear: the Free just before has cleared every one of those fields.
# * m_chain = 0 at the top of GmMusicChainItem::Run: overwritten by Allocate's answer before anything reads it.
# * m_extension[0] = 0 and AtFormat(m_extension, "") in each item's constructor: each alone leaves the same first byte, and nothing reads past it until Configure.
# * The order of the base's keywords, and of the level's: it decides only where colliding words sit in the hash table, which is compared as a whole in the Parse cases; no swap of
#   two words collides differently here (not searched exhaustively).
# Not compared: a path of 128 characters leaves an item's path unterminated, its terminator on the link that Enqueue then overwrites; the bytes past 0x80 differ by side.

